INSERT INTO bai_viet (tieu_de, slug, mo_ta_ngan, noi_dung, hinh_anh, danh_muc, tac_gia, luot_xem, trang_thai, ngay_tao) VALUES
('7 Meo Bao Quan Rau La Xanh Tuoi Lau Hon Trong Tu Lanh', '7-meo-bao-quan-rau-la-xanh-tuoi-lau-hon-trong-tu-lanh', 'Rau la xanh rat de bi heo chi sau 1-2 ngay neu bao quan sai cach. Ap dung 7 meo don gian nay de giu rau tuoi lau gap doi.', '<h2>Tai sao rau la xanh nhanh heo?</h2><p>Rau la xanh chua toi 90% la nuoc. Khi bi mat nuoc hoac tiep xuc khi etylen tu trai cay chin, rau se heo va vang rat nhanh.</p><h2>Meo 1: Khong rua rau truoc khi cat</h2><p>Day la sai lam pho bien nhat. Do am thua tao dieu kien vi khuan phat trien. Chi rua ngay truoc khi dung.</p><h2>Meo 2: Boc rau trong khan giay am</h2><p>Dung khan giam lam am nhe goi quanh bo rau roi cho vao tui zip. Thay khan moi 2 ngay.</p><h2>Meo 3: Cam vao ly nuoc nhu cam hoa</h2><p>Voi rau muong, cai xanh, hung que - cat vat goc 1cm roi cam vao ly nuoc. De nhiet do phong voi hung que vi lanh se lam den la.</p><h2>Meo 4: De dung vi tri trong tu lanh</h2><p>Ngan giua tu lanh, tranh xa ngan da va quat gio. Nhiet do ly tuong 4-8 do C.</p><h2>Meo 5: Tac rieng khoi trai cay</h2><p>Tao, chuoi, ca chua tiet khi etylen lam rau vang nhanh. De rau va trai cay o ngan khac nhau.</p><h2>Meo 6: Dung hop kin co lo thong hoi</h2><p>Lo thong hoi giup luu thong khi vua du. Lot khan giay day hop de hut am.</p><h2>Meo 7: Chan so va cap dong</h2><p>Chan 30-60 giay, ngam nuoc da ngay, de ro roi cap dong. Bao quan duoc 2-3 thang.</p><h2>Thoi gian bao quan tham khao</h2><ul><li><strong>Xa lach:</strong> 5-7 ngay trong hop kin</li><li><strong>Rau muong:</strong> 3-5 ngay boc khan giay</li><li><strong>Hung que:</strong> 7-10 ngay cam ly nuoc nhiet do phong</li><li><strong>Rau da cap dong:</strong> 2-3 thang</li></ul>', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800', 'Meo Bao Quan', 'Admin', 128, 1, '2026-07-10 08:00:00'),

('Bao Quan Ca Chua Dung Cach - Dung De Trong Tu Lanh!', 'bao-quan-ca-chua-dung-cach-dung-de-trong-tu-lanh', 'Nhieu nguoi co thoi quen cho ca chua vao tu lanh nhung day lai la cach lam mat di huong vi tu nhien.', '<h2>Tai sao khong nen de ca chua trong tu lanh?</h2><p>Nhiet do lanh duoi 12 do C ngung hoat dong enzyme tao huong vi. Khi lay ra, enzyme khong phuc hoi - ca chua mat vi ngot, tro nen bot va nhat.</p><h2>Bao quan ca chua chua chin</h2><p>De o <strong>nhiet do phong</strong>, tranh anh nang. Dat cuong huong xuong duoi de chan khong khi xam nhap. Ca chua chin sau 3-7 ngay.</p><h2>Bao quan ca chua da chin</h2><p>De duoc 2-3 ngay o nhiet do phong. Dat cuong huong xuong, tranh chong len nhau. Da cat thi boc mang thuc pham vao tu lanh, dung trong 2 ngay.</p><h2>Bao quan lau dai: lam ca chua co dac</h2><p>Xay nhuyen, nau voi muoi va dau an cho set lai, cho vao hu thuy tinh tiet trung. Tu lanh 1 tuan hoac cap dong 3 thang.</p><h2>Dau hieu ca chua hong</h2><ul><li>Xuat hien vet moc trang hoac xanh</li><li>Vo nhan nheo, bam vao thay nhao</li><li>Mui chua hoac kho chiu</li></ul><h2>Meo tu nong dan</h2><p>Dat 1-2 qua tao chin canh ca chua xanh - tao tiet khi etylen giup ca chua chin nhanh hon 1-2 ngay.</p>', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800', 'Meo Bao Quan', 'Admin', 95, 1, '2026-07-12 09:00:00'),

('Khoai Tay, Hanh Cu, Toi - Bo Ba Gia Vi Can Biet Cach Bao Quan', 'khoai-tay-hanh-cu-toi-bo-ba-gia-vi-can-biet-cach-bao-quan', 'Khoai tay, hanh va toi la 3 thuc pham hau nhu nha nao cung co nhung thuong bi hong do bao quan sai cach.', '<h2>Khoai tay - tranh anh sang va do am</h2><p>Khoai gap anh sang san sinh solanine - chat doc nhe lam khoai co vi dang va xuat hien mau xanh tren vo.</p><ul><li>De noi <strong>toi, kho ráo, thoang mat</strong></li><li>Khong de trong tui nylon kin - khoai can duoc tho</li><li>Nhiet do ly tuong: 7-10 do C</li><li>Khong de canh hanh vi hoi am tu hanh day nhanh moc mam</li></ul><p>Bao quan dung giu duoc <strong>2-3 thang</strong>.</p><h2>Hanh cu - can thong thoang</h2><ul><li>De trong ro hoac tui luoi - khong dung tui nylon</li><li>Noi kho ráo, nhiet do phong</li><li>Hanh da boc vo: boc kin tu lanh, dung trong 1-2 tuan</li></ul><p>Hanh cu nguyen vo bao quan duoc <strong>1-2 thang</strong>.</p><h2>Toi - don gian nhat</h2><p>Toi ca dau duoc <strong>3-6 thang</strong> o nhiet do phong. Da tac te thi dung trong 10 ngay.</p><p><strong>Meo hay:</strong> Ngam toi boc vo trong dau an, hu thuy tinh tu lanh - dung 1 thang va dau co them huong vi toi thom.</p><h2>Tuyet doi khong lam</h2><ul><li>Khong de khoai trong tu lanh - tinh bot thanh duong, den khi chien</li><li>Khong de hanh toi khoai canh nhau - thai khi lam nhau hong nhanh</li><li>Khong rua truoc khi cat - am ut gay moc</li></ul>', 'https://images.unsplash.com/photo-1508747703725-719777637510?w=800', 'Meo Bao Quan', 'Admin', 204, 1, '2026-07-13 10:00:00'),

('Cau Chuyen Tu Nong Trai: Hanh Trinh Cua Bo Rau Tu Dat Den Tay Ban', 'cau-chuyen-tu-nong-trai-hanh-trinh-cua-bo-rau-tu-dat-den-tay-ban', 'Dang sau moi bo rau la cau chuyen cua nhung nguoi nong dan thuc khua day som, cham hut tung luong dat de mang den san pham tuoi ngon nhat.', '<h2>4 gio sang - khi ca nha con ngu</h2><p>Anh Nguyen Van Tam, 52 tuoi, nong dan trong rau o Cu Chi da co 20 nam gan bo voi ruong rau. Moi ngay anh thuc luc 4 gio sang. Ly do don gian: rau hai luc sang som con dam suong se tuoi va gion hon, bao quan duoc lau hon.</p><p>"Rau ma hai nang len roi thi heo nhanh lam, ban khong duoc gia", anh Tam chia se.</p><h2>Quy trinh cham soc khong phan hoa hoc</h2><p>Anh Tam chuyen sang canh tac huu co tu 2018. Giai doan dau nang suat giam 30% nhung doi lai rau ngon hon va duoc nguoi tieu dung uu chuong hon. Anh dung phan trun que tu uy va dich toi ớt pha loong de duoi sau benh.</p><h2>Tu ruong den xe lanh trong 2 tieng</h2><p>Sau thu hoach, rau duoc chon loc tai cho - loai bo la vang, la sau. Xep vao thung xop co nuoc da. Xe lanh Cho Nong San den lay truoc 7 gio sang.</p><h2>Bo rau 15.000d va nhung dieu an sau</h2><p>Chi phi san xuat rau sach cao hon 40-50% so voi rau thuong. Khi ban mua tai Cho Nong San, hon 70% so tien tra truc tiep cho nong dan - khong qua nhieu tang trung gian.</p>', 'https://images.unsplash.com/photo-1500651230702-0e2d8a49d4ad?w=800', 'Tin Tuc', 'Admin', 312, 1, '2026-07-14 07:00:00'),

('5 Mon Ngon Tu Rau Cu Theo Mua - Vua Ngon Vua Bo Duong', '5-mon-ngon-tu-rau-cu-theo-mua-vua-ngon-vua-bo-duong', 'An theo mua giup tiet kiem chi phi, dam bao rau cu ngon va bo duong nhat vi duoc thu hoach dung thoi diem.', '<h2>Mon 1: Canh rau muong nau toi (10 phut)</h2><p><strong>Nguyen lieu:</strong> 300g rau muong, 3 te toi bam, dau an, nuoc mam, muoi.</p><p><strong>Cach lam:</strong> Phi tho toi. Do 500ml nuoc dun soi. Cho rau muong vao, day nap 2 phut. Nem vua an. Tat bep ngay khi rau vua chin de giu mau xanh.</p><p><strong>Meo:</strong> Vut them chanh truoc khi an, canh se thanh mat hon.</p><h2>Mon 2: Ca chua nhiu thit hap (20 phut)</h2><p><strong>Nguyen lieu:</strong> 4 qua ca chua to, 200g thit xay, nam mo, hanh la, nuoc mam, tieu.</p><p><strong>Cach lam:</strong> Khoet bo ruot ca chua. Tron thit xay voi nam mo, hanh la, gia vi. Nhiu vao ca chua. Hap 15-18 phut.</p><h2>Mon 3: Xao cai ngot toi gung (8 phut)</h2><p>Phi toi gung o lua lon. Cho cai vao xao nhanh tay lua to nhat. Them dau hao, muoi, ruoi vai giot dau me. Khong xao qua 3 phut de rau gion xanh.</p><h2>Mon 4: Sup khoai tay ca rot (25 phut)</h2><p>Xao hanh toi voi bo. Them khoai tay va ca rot, do nuoc dung nau 15 phut. Xay nhuyen. Them kem tuoi, nem muoi tieu.</p><h2>Mon 5: Salad rau cu tron dau me (5 phut)</h2><p>Tron dau me, giam gao, duong, muoi thanh nuoc sot. Xep rau ra dia, ruoi nuoc sot, rac hat me rang.</p>', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800', 'Tin Tuc', 'Admin', 178, 1, '2026-07-15 08:00:00'),

('Rau Cu Mua Nay Dang Ngon Nhat - Dung Bo Lo 8 Loai Nay', 'rau-cu-mua-nay-dang-ngon-nhat-dung-bo-lo-8-loai-nay', 'Moi mua deu co rau cu dang o giai doan ngon va re nhat. Biet chon dung mua vu giup tiet kiem ma van co nguyen lieu tuoi ngon nhat.', '<h2>1. Ca chua - dang vao mua thu hoach ro</h2><p>Ca chua dang trong mua cao diem tu Da Lat va Ha Nam. Qua to, do deu, vi ngot dam. Gia dang o muc thap nhat trong nam.</p><h2>2. Bap cai - ngot va gion nhat vua mua lanh</h2><p>Bap cai can thoi tiet mat de phat trien tot. Thu hoach cuoi nam thuong chac tay, la nhieu va vi ngot thanh dac trung.</p><h2>3. Ca rot Da Lat - dang vu chinh</h2><p>Mau cam dam dep, vi ngot tu nhien va it xo. Ngon nhat Viet Nam nho khi hau cao nguyen.</p><h2>4. Sup lo trang va xanh</h2><p>Chon qua co hoa deu mau, chac tay, chua co dot nau. Rat giau vitamin C.</p><h2>5. Khoai lang tim Nhat</h2><p>Dang vu thu hoach tu mien Trung. Vi ngot bui, mau tim dep, giau anthocyanin chong oxy hoa.</p><h2>6. Rau cai ngot va cai thia</h2><p>Thoi tiet mat la dieu kien ly tuong. La xanh muot, than gion, it sau benh.</p><h2>7. Nam cac loai</h2><p>Mua thu dong la mua cua nam. Dong co tuoi, nam rom, kim châm dang doi dao va gia hop ly.</p><h2>8. Dau Ha Lan</h2><p>Dang vao mua hai tuoi. Ngot tu nhien, chon qua vo xanh tuoi, bam vao nghe snap gion la dat.</p>', 'https://images.unsplash.com/photo-1518843875459-f738682238a6?w=800', 'Tin Tuc', 'Admin', 89, 1, '2026-07-16 09:00:00');
